fun main() {
    val stack = mutableListOf("Home", "Feed")
    fun navigate(dest: String, singleTop: Boolean = false) {
        if (singleTop && stack.last() == dest) return
        stack += dest
    }
    navigate("Feed")
    navigate("Feed", singleTop = true)
    navigate("Profile", singleTop = true)
    println(stack.joinToString(" > "))
}

fun main() {
    val stack = ArrayDeque(listOf("Splash", "Login", "Otp"))
    fun navigate(dest: String, popUpTo: String, inclusive: Boolean) {
        while (stack.last() != popUpTo) stack.removeLast()
        if (inclusive) stack.removeLast()
        stack.addLast(dest)
    }
    navigate("Home", popUpTo = "Login", inclusive = true)
    println(stack)
}

